export const SS14_MECHANICS = {"season":"SS14","releaseVerified":false,"generatedAt":"2026-10-16T16:11:18.027Z","pages":{"en/Damage_Form":{"sourceUrl":"https://tlidb.com/en/Damage_Form","sourcePageSha256":"e8d528aa0d867b80511b7e4a10e9e0ecb5c984aed45a5a2d1baf0feedb002d7d","locale":"en","slug":"Damage_Form","season":"SS14","kind":"help","title":"Damage Form","body":"There are 5 ways to deal damage in the game: Hit Damage, Damage Over Time (DoT), Secondary Damage, Damage Reflection, and True Damage.\nHit Damage\nHit Damage is usually dealt by Attacks or Spells and is settled each time. Unless specified, damage dealt by skills is Hit Damage.\nThe following mechanics can affect Hit Damage:\nAccuracy and Evade, Armor, Critical Strike, conversion or addition of the type of damage dealt, conversion of the type of damage taken, Double Damage, Injury Transfer, Injury Buffer, Block, Damage Avoidance, Severe Injury.\nDamage Over Time (DoT)\nDamage Over Time effects deal damage to their targets continuously for a period of time.\nThe following mechanics can affect Damage Over Time:\nAffliction, Reaping, conversion of the type of damage taken.\nThe following mechanics will not affect Damage Over Time: Accuracy and Evasion, Armor, Critical Strike, conversion or addition of the type of damage dealt, Double Damage, Injury Transfer, Injury Buffer, Block, Damage Avoidance, Severe Injury.\nSecondary Damage\nSecondary Damage is usually dealt as a side effect of certain actions, such as \"Defeated enemies will explode\".\nSecondary Damage is neither Hit Damage nor Damage Over Time.\nThe following mechanics can affect Secondary Damage: Conversion of the type of damage taken, Armor, and Damage Avoidance.\nDamage Reflection\nDeals a certain amount of reflected damage to the attacker when the defender takes Hit Damage or Secondary Damage.\nTrue Damage\nTrue Damage is the final damage dealt based on a fixed percentage of other forms of damage.\nTrue Damage is not further affected by most bonuses and ignores Resistance and Armor.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Damage_Calculation":{"sourceUrl":"https://tlidb.com/en/Damage_Calculation","sourcePageSha256":"08687aa490daca31d440f7ab374f486be44cdb9348ab3330ea752227e27529af","locale":"en","slug":"Damage_Calculation","season":"SS14","kind":"help","title":"Damage Calculation","body":"Damage = Base Damage x (1+ all non-additional bonus percentages) x (1 + additional bonus percentage 1) x (1 + additional bonus percentage 2)...\nSimilar to the calculation of stats, damage = Base Damage x (1 + all damage increase percentages) x (1 + additional damage increase percentage 1) x (1 + additional damage increase percentage 2)...","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Amplified_Damage_Over_Time":{"sourceUrl":"https://tlidb.com/en/Amplified_Damage_Over_Time","sourcePageSha256":"9bd735516f41748839bd258b615523292a2adea9c006248a3f4610fb97659e88","locale":"en","slug":"Amplified_Damage_Over_Time","season":"SS14","kind":"help","title":"Amplified Damage Over Time","body":"Affliction is a negative status that additionally increases Damage Over Time taken by units.\nAffliction is a negative effect that is inflicted on an enemy at the same time as Damage Over Time. All DoT effects share the same Affliction effect. While Affliction lasts on a unit, it gradually accumulates Affliction rating according to the \"Affliction Per Second\" stat of the one who inflicted DoT effect, up to the maximum of 100 Affliction.\nEach point of Affliction increases Damage Over Time taken by the enemy by an additional 1%% (up to 100%% at 100 Affliction). This effect is affected by the \"Affliction Effect\".","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Damage_Over_Time_Reaping":{"sourceUrl":"https://tlidb.com/en/Damage_Over_Time_Reaping","sourcePageSha256":"fcd349205e1b8cf06bc16450d6a50ff2cce4d7be2efd29edbfbe71ec74cf3e91","locale":"en","slug":"Damage_Over_Time_Reaping","season":"SS14","kind":"help","title":"Damage Over Time Reaping","body":"Reaping can settle an equivalent to a certain duration of Damage Over Time acting on a unit.\nWhen Reaping, the active Damage Over Time on the target will be settled at once according to the given time and then deal an equal amount of True Damage.\nReaping only applies to Damage Over Time you deal. The Damage Over Time dealt by other units can't be settled by your Reaping.\nReaping generally has a Recovery Time, which is affected by the Reaping Recovery Speed.\nThe Damage Over Time duration settled by Reaping is affected by affix bonuses such as: \"+X% Reaping Duration\".","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Summon":{"sourceUrl":"https://tlidb.com/en/Summon","sourcePageSha256":"b512bcfaa6529e83726fa0ed7ece4fe5732a565254b3471c6b282695494ec302","locale":"en","slug":"Summon","season":"SS14","kind":"help","title":"Summon","body":"Summon Skills can be used to summon different types of Minions. Minions will automatically cast skills at enemies within their Tracking Area.\nSummon Skills can be used to summon different types of Minions. Minions will automatically cast skills at enemies within their Tracking Area. Each type of Minion has a different Tracking Area.\nMinions are completely independent of the player and have their own stats. Only effects that explicitly increase Minion stats will be applied to Minions (for example: +10% Minion Damage).\nHits, damage dealt, defeats, etc., of Minions and the player are settled separately, but the defeats of Minions count as the players' defeats when settling XP, drops, etc.\nMinion Quantity\nThe number of Minions a player can have is jointly controlled by the skill's Max Summonable Minions and Max Minions In Map. The skill's Max Summonable Minions cannot exceed the Max Minions In Map.\nThe Max Summonable Minions of skills that summon the same type of Minion is the highest number among these skills. The total number of Minions summoned by these skills won't exceed this number.\nFor example: There are 2 Summon Machine Guard skills, of which 1 can summon 6 Machine Guards and the other can summon 4 Machine Guards. In this situation, only a total of 6 Machine Guards can be summoned by these 2 skills.\nMinion Types\nMinions are divided into Synthetic Troops and Spirit Magi.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Synthetic_Troop":{"sourceUrl":"https://tlidb.com/en/Synthetic_Troop","sourcePageSha256":"175eb626df3b0093d06147023b3eecdb62805d84207765f761668912a48f7603","locale":"en","slug":"Synthetic_Troop","season":"SS14","kind":"help","title":"Synthetic Troop","body":"Synthetic Troops are a type of Minion. Skills that summon Synthetic Troops are typically Active Skills.\nSynthetic Troops are a type of Minion. Skills that summon Synthetic Troops are typically Active Skills.\nThe max number of Synthetic Troop Minions in a map is 6.\nEach type of Synthetic Troop has different skills, and their stats receive bonuses from Command-related effects.\nCommand\nThe player gains Command after equipping a skill that can be used to summon Synthetic Troops.\nThe minimum value of Command is -100, the maximum value is 100, and the initial value is 0.\nEvery point of Command grants Synthetic Troop Minions +3%% additional damage, -2%% additional damage taken, and +2%% Movement Speed, as well as increasing their Tracking Area.\nCommand is generally not negative, but some special effects will reduce it to lower than 0. When Command is a negative value, the damage bonus granted by each point of Command will always be 0, the Tracking Area will be reduced accordingly, and the Synthetic Troop will be defeated after 5s. When Command is not negative, the time will be refreshed.\nWhen Command is not 0, 13 Command will be reduced/granted (depending on whether the current Command is positive or negative) per second until Command becomes 0 again. For every 10 (or -10) Command increased (or decreased), the amount of Command reduced/granted per second is +7 until the total Command becomes 0.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Spirit_Magus":{"sourceUrl":"https://tlidb.com/en/Spirit_Magus","sourcePageSha256":"be7902403555166a4723d6ecb3dd0ae7eed8e7b4ee2667644f85064436b5781f","locale":"en","slug":"Spirit_Magus","season":"SS14","kind":"help","title":"Spirit Magus","body":"Spirit Magi are a type of Minion. Skills that summon Spirit Magi are typically Passive Skills.\nSpirit Magi are a type of Minion. Skills that summon Spirit Magi are typically Passive Skills.\nThe max number of Spirit Magus Minions in a map is 2.\nEach Spirit Magus has different skills, including Base Skills, Enhanced Skills, Empower Skills, and Ultimate. A Spirit Magus' stats are affected by Growth-related effects and bonuses.\nBase Skill\nSpirit Magi's most frequently used initial skill, which is relatively weak.\nEnhanced Skills\nChance to change the skill into a stronger Enhanced Skill when Spirit Magi use a Base Skill. The chance can be increased, and at 100%, Spirit Magi will no longer use Base Skills and always use Enhanced Skills.\nEmpower Skill\nSpirit Magi are able to use this type of skill from the very beginning. It provides Spirit Magi with a positive effect that increases damage for a period of time and has a cooldown.\nUltimate\nIn Full Bloom, Spirit Magi use their Ultimate with extremely high strength and a cooldown.\nOnly The Forsaken Iris - Growing Breeze can make Spirit Magi enter the Full Bloom state.\nGrowth\nThe Spirit Magi summoned by the player has a stat called Growth.\nGrowth's lower limit is 100 and upper limit is 1000.\nSpirit Magi start off at Stage 1 (100 Growth) and grow into the next stage with every 100 Growth gained until they reach Stage 5 (500 Growth).\nFor every 8 Growth a Spirit Magus has, it gains +1%% Physique. With every stage a Spirit Magus grows, it gains +10%% additional Skill Area and different skill and attribute enhancements:\nAt Stage 2, Spirit Magi have a +30% chance to use Enhanced Skills.\nAt Stage 3, the effect of Spirit Magi's Enhanced Skills is enhanced.\nAt Stage 4, Spirit Magi's Empower Skills gain new effects.\nAt Stage 5, all the attributes of Spirit Magi are increased, and they gain +50%% additional damage, +10%% additional Skill Area, and +30%% additional Movement Speed. Their Tracking Area also increases.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Whimsy":{"sourceUrl":"https://tlidb.com/en/Whimsy","sourcePageSha256":"d0ec9db15a64226805f3c4e93ecd00305d974ae021327a4d7b6782a727631c09","locale":"en","slug":"Whimsy","season":"SS14","kind":"help","title":"Whimsy","body":"+5% additional Spell Damage (multiplies) for 10s","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Whimsy_Signal":{"sourceUrl":"https://tlidb.com/en/Whimsy_Signal","sourcePageSha256":"048557920f75db46dda31cda889205910ecbad0eefb016414baa0fa42e6d7683","locale":"en","slug":"Whimsy_Signal","season":"SS14","kind":"help","title":"Whimsy Signal","body":"+20% additional Spell Damage taken for 5s","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Whimsy_Explosion":{"sourceUrl":"https://tlidb.com/en/Whimsy_Explosion","sourcePageSha256":"a7e2fd7131820d59667f0a22e48817a52c0705e6ef90a40e8ad8450bf6d2dba7","locale":"en","slug":"Whimsy_Explosion","season":"SS14","kind":"help","title":"Whimsy Explosion","body":"Fires a projectile that creates an energy explosion on hit, consuming 100 Whimsy Essence while restoring 25 Ingenuity Essence","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Ingenuity_Overload":{"sourceUrl":"https://tlidb.com/en/Ingenuity_Overload","sourcePageSha256":"66057bd1362ee0cf8fcb46cf4a7b8e8fb482c579a4028f9a53c6f0adc2f78557","locale":"en","slug":"Ingenuity_Overload","season":"SS14","kind":"help","title":"Ingenuity Overload","body":"Triggers your Main Skill once immediately (this skill must be able to activate Spell Burst). +200% additional Max Spell Burst for the skill this time and immediately charges it to the max. Consumes 100 Ingenuity Essence","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/A_Corner_of_Divinity":{"sourceUrl":"https://tlidb.com/en/A_Corner_of_Divinity","sourcePageSha256":"a468c23081edd286c5e8932e5ebc5753dcefabcadd7255465ac367005da51dad","locale":"en","slug":"A_Corner_of_Divinity","season":"SS14","kind":"card","title":"A Corner of Divinity","body":"<Legendary Medium Talent>\n<Legendary Medium Talent>\n(Max Active Divinity Slates: 3)\nThis is a missing fragment of divinity. The waning divinity appears to foreshadow the realms' impending end.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Fallen_Starlight":{"sourceUrl":"https://tlidb.com/en/Fallen_Starlight","sourcePageSha256":"e526b68ccfd1a46a716024d8ea8e1fb8e40d1b4f1c79e2eeff2b72dc89c7fec4","locale":"en","slug":"Fallen_Starlight","season":"SS14","kind":"card","title":"Fallen Starlight","body":"<Micro Talent>\n<Micro Talent>\n<Micro Talent or Medium Talent>\n<Medium Talent>\n(Max Active Divinity Slates: 3)\nAfter about ten thousand years of growth, the starlight is finally mature and falls to the dark earth like fruits.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Sparks_of_Moth_Fire":{"sourceUrl":"https://tlidb.com/en/Sparks_of_Moth_Fire","sourcePageSha256":"76da01eb11187a05983e18c01b5035a053c798f1802dc4c7a16991ec99d7177a","locale":"en","slug":"Sparks_of_Moth_Fire","season":"SS14","kind":"card","title":"Sparks of Moth Fire","body":"Copies the last Talent on the adjacent slate above to this slate. Unable to copy the Core Talent.\nCopies the last Talent on the adjacent slate on the left to this slate. Unable to copy the Core Talent.\nCopies the last Talent on the adjacent slate below this slate. Unable to copy the Core Talents.\nCopies the last Talent on the adjacent slate on the right to this slate. Unable to copy the Core Talent.\n(Max Active Divinity Slates: 3)\nThe candle moth has become part of the fire... But it still has successors who keep flying to her for the dim light.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/When_Sparks_Set_the_Prairie_Ablaze":{"sourceUrl":"https://tlidb.com/en/When_Sparks_Set_the_Prairie_Ablaze","sourcePageSha256":"175af616d12b0bcadd26ec734d1fdf26f4db125504418925d0c3357a96df8c9a","locale":"en","slug":"When_Sparks_Set_the_Prairie_Ablaze","season":"SS14","kind":"card","title":"When Sparks Set the Prairie Ablaze","body":"Copies the last Talent on all adjacent slates. Unable to copy Core Talents.\n(Max Active Divinity Slate: 1)\nThe latecomers pounced on the moths that started the fire until the surroundings were fully ignited by the scattered sparks, making the radiance greater than ever.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Space_Rift":{"sourceUrl":"https://tlidb.com/en/Space_Rift","sourcePageSha256":"67aef9db3dd841b44fd5f1737a76ca814faf85ab46e899c127cec3a75355b60e","locale":"en","slug":"Space_Rift","season":"SS14","kind":"card","title":"Space Rift","body":"Copies the Medium Talents, Legendary Medium Talents, and Ultimate Nether King Talents on the adjacent slate on the left to this slate\nCopies the Medium Talents, Legendary Medium Talents, and Ultimate Nether King Talents on the adjacent slate on the right to this slate\nThe gods are gone, but the door is still there, as if she had never left.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Residence_of_Stars":{"sourceUrl":"https://tlidb.com/en/Residence_of_Stars","sourcePageSha256":"d6a96043ad81ee80bd2ac435e8083a1cc89ff2cdf74016d177e5880fa31348c5","locale":"en","slug":"Residence_of_Stars","season":"SS14","kind":"card","title":"Residence of Stars","body":"Copies the Medium Talents on the adjacent slate to this slate. Unable to copy Legendary Medium Talents.\nAfter wandering for about ten thousand years, the starlight is returning home, the only place where it can find entities alike.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Pedigree_of_Gods":{"sourceUrl":"https://tlidb.com/en/Pedigree_of_Gods","sourcePageSha256":"dd671d968cc230535fb993c68d999ea958a0c513bebb8fe1b8db9b1509a995ca","locale":"en","slug":"Pedigree_of_Gods","season":"SS14","kind":"card","title":"Pedigree of Gods","body":"<Micro Talent or Medium Talent>\n<Micro Talent or Medium Talent>\n<Medium Talent or Lv.1 Core Talent>\n<Lv.2 Core Talent>\n(Max Active Divinity Slate: 1)\nIt records the origin and end of every god. During the times when the gods are long gone, people come here to learn about their deeds.","tags":["Require lv 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Overpower":{"sourceUrl":"https://tlidb.com/en/Overpower","sourcePageSha256":"016b3c9432c7decef4541cbccfab78b1f574e8493025b51c708eb483955124bc","locale":"en","slug":"Overpower","season":"SS14","kind":"card","title":"Overpower","body":"Main Stat:\nStrength, Intelligence\nCast Speed\n1.43 s\nEffectiveness of added damage\n54%\nSimple\nCasts the skill and pummels the ground in front, dealing Attack Physical Damage equal to 54% Base Damage on hit.\nDetails\nOverpower:\nDeals Attack Physical Damage equal to 54% Base Damage","tags":["Attack","Physical","Area","Melee"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Onslaught_Punch":{"sourceUrl":"https://tlidb.com/en/Onslaught_Punch","sourcePageSha256":"0aec12ee00e065db592f246a5797410806f48302b7315b25a487bb2bc9d72d07","locale":"en","slug":"Onslaught_Punch","season":"SS14","kind":"card","title":"Onslaught Punch","body":"Main Stat:\nStrength, Intelligence\nCast Speed\n1.25 s\nCooldown\n0.1 s\nEffectiveness of added damage\n83%\nSimple\nCasts the skill and dashes to the target enemy. Stops before the enemy and attacks the square area in front, dealing Attack Physical Damage equal to 83% Base Damage.\nDetails\nOnslaught Punch:\nDeals Attack Physical Damage equal to 83% Base Damage","tags":["Attack","Physical","Area","Melee"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Glacier_Ripples":{"sourceUrl":"https://tlidb.com/en/Glacier_Ripples","sourcePageSha256":"354f0145b89c4d8f369ac2e6e201f67f99df332af333cf52f42219d8a9f8f857","locale":"en","slug":"Glacier_Ripples","season":"SS14","kind":"card","title":"Glacier Ripples","body":"Main Stat:\nIntelligence\nCast Speed\n1.25 s\nEffectiveness of added damage\n110%\nSimple\nCasts the skill to attack in a fan-shaped area in front, dealing Spell Cold Damage equal to 110% of Base Damage.\nDetails\nGlacier Ripples:\nDeals Spell Cold Damage equal to 110% of Base Damage","tags":["Base Skill","Spell","Cold","Area"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Frost_Release":{"sourceUrl":"https://tlidb.com/en/Frost_Release","sourcePageSha256":"6be755ad3fb35dbb143e52e374c8a161d77bd381b748c5bb1cedf0cfe56739c1","locale":"en","slug":"Frost_Release","season":"SS14","kind":"card","title":"Frost Release","body":"Main Stat:\nIntelligence\nCast Speed\n1.67 s\nCooldown\n10 s\nEffectiveness of added damage\n72%\nSimple\nCasts this skill and spreads Freezing Air within a certain area around the caster, dealing Spell Cold Damage equal to 72% Base Damage.\nCasts this skill and gains Euphoria: The next 5 other skill(s) deal +81% additional damage. After casting another skill, this bonus -15% for 6 s, stacking up to 5 time(s). Multiple stacks of the skill effect multiply\nWhile this skill lasts, you gain 15 Cold Resistance Penetration\nDetails\nCasts the skill and gains Euphoria:\nThe next 5 use(s) of other non-Channeled Skills deal +81 % additional Hit Damage while the skill lasts. -15 % to this damage bonus after casting another skill\nLasts 6 s.\nStacks up to 5 time(s)\nMultiple stacks of the skill effect multiply.\nFrost Release:\nDeals Spell Cold Damage equal to 72% of Base Damage\n+15 % Cold Resistance Penetration while this skill lasts\nWhen at Stage 4 or higher, triggers this skill after casting 5 other skills","tags":["Empower","Spell","Cold","Area","Persistent"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Permafrost_Cast":{"sourceUrl":"https://tlidb.com/en/Permafrost_Cast","sourcePageSha256":"79c3a1e1cd984017484b8298f75733ea78b808fde875d99cdda3948b26cd284d","locale":"en","slug":"Permafrost_Cast","season":"SS14","kind":"card","title":"Permafrost Cast","body":"Main Stat:\nIntelligence\nCast Speed\n1.25 s\nEffectiveness of added damage\n300%\nSimple\nCast this skill to pummel the ground in front, dealing Spell Cold Damage equal to 300% Base Damage.\nDetails\nPermafrost Cast:\nDeals Spell Cold Damage equal to 300% of Base Damage.\nInflicts Frostbite when this skill deals Hit Cold Damage\nWhen at Stage 3 or higher, the skill deals +1 % additional damage for every 3 Frostbite Rating the enemy has","tags":["Enhanced Skill","Spell","Cold","Area"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Ice_Earthshaker":{"sourceUrl":"https://tlidb.com/en/Ice_Earthshaker","sourcePageSha256":"21ea8acc189332d37757981a2b0f276c2e4aa787601fb1638f6de4f9c9812ee2","locale":"en","slug":"Ice_Earthshaker","season":"SS14","kind":"card","title":"Ice Earthshaker","body":"Main Stat:\nIntelligence\nCast Speed\n0.67 s\nCooldown\n8 s\nEffectiveness of added damage\n2064%\nSimple\nCasts the skill and launches an ice blast forward, dealing Spell Cold Damage equal to 2064% of Base Damage.\nDetails\nIce Earthshaker:\nDeals Spell Cold Damage equal to 2064% of Base Damage.\nInflicts Frostbite when this skill deals Hit Cold Damage","tags":["Ultimate","Spell","Cold","Area"],"rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"ko/Damage_Form":{"sourceUrl":"https://tlidb.com/ko/Damage_Form","sourcePageSha256":"a9ff9383adf7f4451db00442710b8834283134944051856d313a057e7f8039bc","locale":"ko","slug":"Damage_Form","season":"SS14","kind":"help","title":"Damage Form","body":"현재 게임 내 대미지 형식은 적중 대미지, 지속 대미지, 간접 대미지, 반사 대미지, 트루 대미지의 5가지가 있습니다.\n적중 대미지\n적중 대미지는 보통 공격이나 주술을 통해 부여되며, 한 번에 카운트되는 대미지입니다. 특별한 설명이 없을 경우, 스킬로 주는 대미지는 모두 적중 대미지입니다.\n다음은 적중 대미지의 고유 메커니즘입니다:\n명중/회피, 아머, 크리티컬, 주는 대미지 유형의 전환 및 추가, 받는 대미지 유형의 전환, 이중 대미지, 대미지 전이, 대미지 완화, 막기, 대미지 면역, 중상.\n지속 대미지\n지속 대미지는 일정 시간 동안 계속해서 타깃에게 대미지를 입힙니다.\n다음 매커니즘은 지속 대미지에 영향을 줄 수 있습니다.\n심화, 수확, 받는 대미지 유형의 전환.\n다음 매커니즘은 지속 대미지에 영향을 줄 수 없습니다. 명중/회피, 아머, 크리티컬, 입히는 대미지 유형의 전환 및 추가, 이중 대미지, 대미지 전이, 대미지 완화, 막기, 대미지 면역, 중상.\n간접 대미지\n간접 대미지는 보통 어떤 행위의 부가효과로 나타납니다. 예: 처치 시 적이 폭발한다.\n간접 대미지는 적중 대미지도 아니고, 지속 대미지도 아닙니다.\n다음 매커니즘은 간접 대미지에 영향을 줄 수 있습니다.받는 대미지 유형의 전환, 아머, 대미지 면역.\n반사 대미지\n방어자가 적중 대미지 또는 간접 대미지를 받을 때, 공격자에게 일정량의 반사 대미지를 입힐 수 있습니다.\n트루 대미지\n트루 대미지는 다른 대미지의 고정 비율을 바탕으로 최종적으로 형성되는 대미지다.\n트루 대미지는 더 이상 대다수 보너스의 영향을 받지 않으며, 저항, 아머를 무시한다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Damage_Calculation":{"sourceUrl":"https://tlidb.com/ko/Damage_Calculation","sourcePageSha256":"6f0cd006b88fff05fef70b80cf3cb64c9add294c7fa9d0e40bc9462f563e60ad","locale":"ko","slug":"Damage_Calculation","season":"SS14","kind":"help","title":"Damage Calculation","body":"대미지 수치=기본 대미지*(1+모든 비추가 비율 보너스)*(1+추가 비율 보너스1)*(1+추가 비율 보너스2)...\n속성의 계산 방법과 비슷합니다. 대미지 계산 값=기본 대미지*(1+모든 비율 증가 대미지)*(1+추가 비율 증가 대미지1)*(1+추가 비율 증가 대미지2)...","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Amplified_Damage_Over_Time":{"sourceUrl":"https://tlidb.com/ko/Amplified_Damage_Over_Time","sourcePageSha256":"a27c59347078b894f9c092e0cbe13e685fe1b8b85bc722f2bf7d86f0489e8594","locale":"ko","slug":"Amplified_Damage_Over_Time","season":"SS14","kind":"help","title":"Amplified Damage Over Time","body":"심화는 유닛이 받는 지속 대미지를 별도로 추가시키는 디버프입니다.\n적에게 지속 대미지를 입힐 때 심화 디버프도 부여됩니다. 모든 지속 대미지가 심화 효과 하나를 공유합니다. 심화 보유 시, 지속 대미지 시전자의 '초당 시전 심화' 속성에 따라 유닛에게 심화 수치가 점차 누적되며, 누적 상한은 100입니다.\n심화 1포인트 당 적이 받는 지속 대미지가 1%% 별도 추가합니다(100포인트 시 100%%), 이 효과는 심화 효과의 영향을 받습니다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Damage_Over_Time_Reaping":{"sourceUrl":"https://tlidb.com/ko/Damage_Over_Time_Reaping","sourcePageSha256":"18232fecbc1766491588d3804e96fb710ece4cf5fa3a184699bb5a3ec5856a42","locale":"ko","slug":"Damage_Over_Time_Reaping","season":"SS14","kind":"help","title":"Damage Over Time Reaping","body":"수확은 유닛이 일정 시간 동안 가지고 있는 지속 대미지를 카운트할 수 있습니다.\n수확 부여 시, 타깃에게 적용중인 모든 지속 대미지에 대해, 설정된 시간에 따라 총 대미지가 1회 카운트되며, 그와 동일량의 트루 대미지를 입힙니다.\n수확은 자신이 입힌 지속 대미지에만 적용되며, 다른 유닛이 입힌 지속 대미지는 자신의 수확으로 카운트되지 않습니다.\n수확은 일반적으로 회복 시간이 있으며, 해당 회복 시간은 수확 회복 속도의 영향을 받습니다.\n수확 시간은 '수확 시간 X% 증가'와 같은 옵션으로 보너스를 획득할 수 있습니다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Summon":{"sourceUrl":"https://tlidb.com/ko/Summon","sourcePageSha256":"fe1389ca05494d6bd72c21a5af54f9e56d92a5a00056ea95f1364814158165c9","locale":"ko","slug":"Summon","season":"SS14","kind":"help","title":"Summon","body":"소환 스킬은 다양한 종류의 소환체를 소환할 수 있습니다. 소환체는 자동으로 정찰 범위 내의 적에게 스킬을 사용합니다.\n소환 스킬로 다양한 종류의 소환체를 소환할 수 있습니다. 소환체는 자동으로 정찰 범위 내의 적에게 스킬을 사용합니다. 소환체에 따라 정찰 범위도 다릅니다.\n소환체와 유저는 서로 독립된 유닛으로 속성도 서로 독립적입니다. 확실하게 명시된 소환체 속성 증가 효과만 소환체에 적용됩니다(예: 소환체 대미지 10% 증가).\n소환체와 유저는 적중, 입히는 대미지, 적 처치 등의 사건을 각자 독립적으로 카운트합니다. 단, 경험치, 드롭 등의 내용을 결산할 때는 소환체가 처치한 적도 유저가 처치한 것으로 간주합니다.\n소환체 수량\n유저가 보유할 수 있는 소환체 수량은 스킬 소환 상한 및 최대 수량 상한의 제한을 받습니다. 스킬 소환 상한은 최대 수량 상한을 초과하지 않습니다.\n같은 종류의 소환체 스킬들을 사용할 경우, 최대 소환 가능 횟수가 가장 높은 스킬의 소환 한도가 적용되며, 이 스킬들로 소환된 소환체의 총 수량은 해당 최대 소환 횟수를 초과할 수 없습니다.\n예: 머신 가드 소환 스킬 2개 중 1개는 머신 가드를 6개 소환할 수 있으며, 다른 1개는 4개를 소환할 수 있습니다. 단, 이 두 스킬을 함께 사용 시 총 6개의 머신 가드만 소환할 수 있습니다.\n소환체 종류\n소환체는 스마트 웨폰과 마령으로 나뉩니다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Synthetic_Troop":{"sourceUrl":"https://tlidb.com/ko/Synthetic_Troop","sourcePageSha256":"193c4ea593fbd989a7de42e38c7d0a27617d447b780657520ce424805f3e82f1","locale":"ko","slug":"Synthetic_Troop","season":"SS14","kind":"help","title":"Synthetic Troop","body":"스마트 웨폰은 소환체의 일종으로, 스마트 웨폰을 소환하는 스킬은 일반적으로 액티브 스킬입니다.\n스마트 웨폰은 소환체의 일종으로, 스마트 웨폰을 소환하는 스킬은 일반적으로 액티브 스킬입니다.\n스마트 웨폰 소환체는 최대 6개까지 소환할 수 있습니다.\n스마트 웨폰별로 보유 스킬이 다르며, 해당 속성은 모두 통솔 관련 효과 보너스를 받습니다.\n통솔\n유저가 스마트 웨폰 소환 스킬을 장착하면 통솔 수치를 보유하게 됩니다.\n통솔은 최하 -100, 최대 100, 시작 시 0입니다.\n통솔 1포인트당 스마트 웨폰 대미지 별도 +3%%, 받는 대미지 별도 -2%%, 이동 속도가 +2%% 증가하고 정찰 범위가 증가합니다.\n통솔은 일반적으로 음수가 아니나, 일부 특수효과의 영향으로 0 미만이 될 수 있습니다. 통솔이 음수일 경우, 통솔 1포인트 당 대미지 보너스는 0으로 고정되나 정찰 범위가 감소하며, 5초 후 스마트 웨폰이 처치됩니다. 통솔이 음수가 아닐 경우, 카운트다운이 초기화됩니다.\n통솔이 0이 아닌 경우, 0이 될 때까지 초당 13포인트씩 회복(증가/감소, 현재의 통솔 수치에 따라 결정)되며, 통솔 10(또는 -10)포인트 당 초당 회복값이 +7포인트씩 증가합니다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Spirit_Magus":{"sourceUrl":"https://tlidb.com/ko/Spirit_Magus","sourcePageSha256":"012cb85520296d469e442f322a0cda3b949f66796cfa3dd6bf0acb3229ba0b63","locale":"ko","slug":"Spirit_Magus","season":"SS14","kind":"help","title":"Spirit Magus","body":"마령은 소환체의 일종으로, 마령을 소환하는 스킬은 일반적으로 패시브 스킬입니다.\n마령은 소환체의 일종으로, 마령을 소환하는 스킬은 일반적으로 패시브 스킬입니다.\n마령 소환체의 최대 수량은 2입니다.\n마령별로 보유한 스킬이 다르며, 기본 스킬, 강화 스킬, 자극 스킬, 궁극 스킬로 나뉩니다. 마령의 속성은 모두 성장치 관련 효과 보너스를 받습니다.\n기본 스킬\n마령이 최초에 가장 자주 사용하는 스킬은 강도가 약합니다.\n강화 스킬\n마령이 기본 스킬을 사용하는 경우, 일정 확률로 강도가 더 높은 강화 스킬로 전환됩니다. 확률은 육성할 수 있으며, 100% 도달 시 마령이 더이상 기본 스킬을 사용하지 않고 강화 스킬만 사용합니다.\n자극 스킬\n마령이 최초로 사용하는 스킬로, 사용 후 마령 자신에게 일정 시간 대미지를 강화하는 효과를 제공하며, 쿨타임이 있습니다.\n궁극 스킬\n마령이 만개 상태일 때, 매우 높은 강도와 쿨타임을 보유한 궁극 스킬을 사용합니다.\n속세를 떠난 마령 아이리스-성장의 미풍만 마령에게 만개 형태를 부여할 수 있습니다.\n성장치\n유저가 소환하는 마령은 성장치를 보유합니다.\n성장치는 최저 100, 최고 1000입니다.\n마령은 최초 1티어(성장치 100포인트 보유)로 시작하며, 성장치 100포인트 당 1티어씩 성장하며 최고 5티어(성장치 500)까지 성장할 수 있습니다.\n마령이 성장치 8 포인트 보유 시마다, 체격 +1%%, 승급 시마다 스킬 범위 +10%% 추가, 해당 스킬 및 속성도 강화됩니다.\n2티어까지 성장 시 마령의 강화 스킬 사용 확률이 30% 증가합니다.\n3티어까지 성장 시 마령의 강화 스킬 효과가 강화됩니다.\n4티어까지 성장 시 마령의 자극 스킬 효과가 새로운 효과를 제공합니다.\n5티어까지 성장 시 마령의 속성이 전체적으로 향상되며, 대미지 +50%%, 스킬 범위 +10%%, 이동 속도 +30%%가 추가되고, 마령의 정찰 범위도 증가합니다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Whimsy":{"sourceUrl":"https://tlidb.com/ko/Whimsy","sourcePageSha256":"e31b2f9bca347c0d9288707361ed93cc804c94b29ff8cc658d9cf76b38639310","locale":"ko","slug":"Whimsy","season":"SS14","kind":"help","title":"Whimsy","body":"주술 대미지(곱연산) 별도 +5%, 10 초간 지속한다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Whimsy_Signal":{"sourceUrl":"https://tlidb.com/ko/Whimsy_Signal","sourcePageSha256":"1da2800a7fc3f6aa6bc98f0750ee46247331783a95d116562c52dcefd98f30ac","locale":"ko","slug":"Whimsy_Signal","season":"SS14","kind":"help","title":"Whimsy Signal","body":"받는 주술 대미지 별도 +20%, 5초간 지속된다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Whimsy_Explosion":{"sourceUrl":"https://tlidb.com/ko/Whimsy_Explosion","sourcePageSha256":"4a1dd7172551f8ba8ac22289fa79b4a558fbd8119e5caa5ddb9fa121481d43ad","locale":"ko","slug":"Whimsy_Explosion","season":"SS14","kind":"help","title":"Whimsy Explosion","body":"투사체 1개를 발사하고 적중한 후 1회 에너지 폭발을 일으키고, 기발 에센스 100 포인트를 소모하는 동시에 창의 에센스 25 포인트를 회복한다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Ingenuity_Overload":{"sourceUrl":"https://tlidb.com/ko/Ingenuity_Overload","sourcePageSha256":"8331fe75112338a5c95adce4739149fb64a6c94adb259497c0496e9041f23701","locale":"ko","slug":"Ingenuity_Overload","season":"SS14","kind":"help","title":"Ingenuity Overload","body":"유저의 메인 스킬을 1회 즉시 발동(해당 스킬이 매직 버스트를 활성화할 수 있어야 함), 해당 스킬의 최대 매직 버스트 추가 +200%, 최대 충전으로 간주, 창의 에센스를 100포인트 소모한다.","tags":[],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/A_Corner_of_Divinity":{"sourceUrl":"https://tlidb.com/ko/A_Corner_of_Divinity","sourcePageSha256":"da02072f64ef4fbf5cf935d987f084a72d21e7b349df418f5009f2eec4872337","locale":"ko","slug":"A_Corner_of_Divinity","season":"SS14","kind":"card","title":"신성의 일각","body":"<레전드 중위 재능>\n<레전드 중위 재능>\n(해당 신격의 석판 유효 한도:3)\n조금씩 불완전해지는 신의 존재가 만계의 끝을 암시하고 있는 듯하다.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Fallen_Starlight":{"sourceUrl":"https://tlidb.com/ko/Fallen_Starlight","sourcePageSha256":"6244cd1cbb6aa5c51552d09b0cb7df1fb12cb272828925e0827260121d1629c4","locale":"ko","slug":"Fallen_Starlight","season":"SS14","kind":"card","title":"추락하는 별빛","body":"<하위 재능>\n<하위 재능>\n<하위 재능 또는 중위 재능>\n<중위 재능>\n(해당 신격의 석판 유효 최대치: 3)\n만년을 자라난 별빛들이 무르익어 어둠뿐인 대지에 떨어진다면.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Sparks_of_Moth_Fire":{"sourceUrl":"https://tlidb.com/ko/Sparks_of_Moth_Fire","sourcePageSha256":"e83322eec48cb3d94f924e53ba630591e657cdb914f9445d957ec737efb9a2f6","locale":"ko","slug":"Sparks_of_Moth_Fire","season":"SS14","kind":"card","title":"빛이 된 나방","body":"위쪽 석판의 마지막 재능 한 줄을 해당 석판으로 복제 한다. 핵심 재능은 복제 할 수 없다.\n왼쪽 석판의 마지막 재능 한 줄을 해당 석판으로 복제 한다. 핵심 재능은 복제 할 수 없다.\n아래쪽 석판의 마지막 재능 한 줄을 해당 석판으로 복제 한다. 핵심 재능은 복제 할 수 없다.\n오른쪽 석판의 마지막 재능 한 줄을 해당 석판으로 복제 한다. 핵심 재능은 복제 할 수 없다.\n(해당 신격의 석판 유효 최대치: 3)\n불 속으로 뛰어든 나방은 불의 일부가 되었지만, 여전히 그 불빛을 지키기 위한 자들의 발길이 이어지고 있다.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/When_Sparks_Set_the_Prairie_Ablaze":{"sourceUrl":"https://tlidb.com/ko/When_Sparks_Set_the_Prairie_Ablaze","sourcePageSha256":"6790e329e06bc18eb1482b173d0e27809358f57ab736dddcfe647e052b0eff0e","locale":"ko","slug":"When_Sparks_Set_the_Prairie_Ablaze","season":"SS14","kind":"card","title":"들불 번지는 순간","body":"모든 인접 석판의 마지막 재능 한 줄을 해당 석판으로 복제 한다. 핵심 재능은 복제 할 수 없다.\n(신격의 석판 유효 한도: 1)\n후발 주자들은 계속해서 처음 불을 지핀 나방에게 달려든다. 드문드문한 별빛이 사방에 불을 붙여 전보다 더 빛날 때까지.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Space_Rift":{"sourceUrl":"https://tlidb.com/ko/Space_Rift","sourcePageSha256":"ad74374b5d1923d1a9dd2bb6b7687d2784685ff74629d272671d89e7c4e82344","locale":"ko","slug":"Space_Rift","season":"SS14","kind":"card","title":"우주의 균열","body":"왼쪽 석판의 중위 재능, 레전드 중위 재능과 절대자 명왕 재능을 해당 석판으로 복제 한다.\n오른쪽 석판의 중위 재능, 레전드 중위 재능과 절대자 명왕 재능을 해당 석판으로 복제 한다.\n신은 멀어져 갔지만, 문은 그녀처럼 언제나 그곳에 있다.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Residence_of_Stars":{"sourceUrl":"https://tlidb.com/ko/Residence_of_Stars","sourcePageSha256":"ba067ff75f497ef4589737741123d33f3867ea05d025526d300e2f66e67a5b60","locale":"ko","slug":"Residence_of_Stars","season":"SS14","kind":"card","title":"별들의 고향","body":"인접 석판의 중위 재능을 해당 석판으로 복제 한다. 레전드 중위 재능은 복제할 수 없다.\n만년을 헤매던 별빛들이 서로 닮아있는 존재를 찾아 원래의 자리로 돌아오고 있다.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Pedigree_of_Gods":{"sourceUrl":"https://tlidb.com/ko/Pedigree_of_Gods","sourcePageSha256":"9ffb7f82dd9f309d211fc975b962fa8a010295789f2476ae0c35944112457541","locale":"ko","slug":"Pedigree_of_Gods","season":"SS14","kind":"card","title":"신의 계보","body":"<하위 재능 또는 중위 재능>\n<하위 재능 또는 중위 재능>\n<중위 재능 또는 1레벨 핵심 재능>\n<2레벨 핵심 재능>\n(해당 신격의 석판 유효 최대치: 1)\n천지신명의 시작과 끝이 기록되어있다. 신들이 떠나면 인류는 이를 통해 신들의 업적을 알게 되리라.","tags":["레벨 조건 1"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Overpower":{"sourceUrl":"https://tlidb.com/ko/Overpower","sourcePageSha256":"529ad6771bad11d7ca2bb26758a6d687408fba6391a4a20db9949d93f034747d","locale":"ko","slug":"Overpower","season":"SS14","kind":"card","title":"압도적 스매시","body":"메인 속성:\n힘, 지혜\n시전 속도\n1.43 초\n대미지 배율\n54%\nSimple\n전방의 지면에 펀치를 날리며, 적중 시 기본 대미지의 54% 만큼 공격 물리 대미지를 입힌다.\nDetails\n압도적 스매시:\n기본 대미지의 54% 만큼 공격 물리 대미지를 입힌다.","tags":["공격","물리","범위","근접전"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Onslaught_Punch":{"sourceUrl":"https://tlidb.com/ko/Onslaught_Punch","sourcePageSha256":"22dfaf60ac4c81000078528c1f0a8afe79c7e668ea5aeb741f464999823bdea0","locale":"ko","slug":"Onslaught_Punch","season":"SS14","kind":"card","title":"진격의 주먹","body":"메인 속성:\n힘, 지혜\n시전 속도\n1.25 초\n쿨타임\n0.1 초\n대미지 배율\n83%\nSimple\n선택한 적을 향해 대시하며, 적 앞에서 멈춘 뒤 전방 직사각형 모양 구역에 공격을 가하여 기본 대미지의 83% 만큼 공격 물리 대미지를 입힌다.\nDetails\n진격의 주먹:\n기본 대미지의 83% 만큼 공격 물리 대미지를 입힌다.","tags":["공격","물리","범위","근접전"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Glacier_Ripples":{"sourceUrl":"https://tlidb.com/ko/Glacier_Ripples","sourcePageSha256":"9743b516d12be0993f443664bd16ef9ef4ebdd034cc0f0d16e50587a83729dce","locale":"ko","slug":"Glacier_Ripples","season":"SS14","kind":"card","title":"빙하의 물결","body":"메인 속성:\n지혜\n시전 속도\n1.25 초\n대미지 배율\n110%\nSimple\n전방 부채꼴 모양 구역을 타격하여 기본 대미지의 110% 만큼 주술 냉기 대미지를 입힌다.\nDetails\n빙하의 물결:\n기본 대미지의 110% 만큼 주술 냉기 대미지를 입힌다.","tags":["기본 스킬","주술","냉기","범위"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Frost_Release":{"sourceUrl":"https://tlidb.com/ko/Frost_Release","sourcePageSha256":"700700da29e577431aa4c12f9b0e2f6b6f40aeb50d5e57395227cd735aa1059a","locale":"ko","slug":"Frost_Release","season":"SS14","kind":"card","title":"프리징 릴리즈","body":"메인 속성:\n지혜\n시전 속도\n1.67 초\n쿨타임\n10 초\n대미지 배율\n72%\nSimple\n스킬 시전 시 자신의 일정 범위 내에 한기를 확산시켜, 기본 대미지의 72% 만큼 주술냉기 대미지를 입힌다.\n스킬 시전 시 흥분 획득: 다음 5 회 동안 다른 스킬의 대미지 별도 +81% , 다른 스킬 시전 후, 해당 보너스 -15% , 6 초간 지속, 최대 5 회 중첩, 스킬 효과 중첩 시 곱연산 적용된다.\n해당 스킬 지속 시 자신의 냉기 저항 관통 15\nDetails\n시전 시 흥분 획득:\n스킬 지속 시, 다음 5 회간 기타 비 채널링 스킬의 적중 대미지 추가 +81 % . 기타 스킬 시전 후 해당 보너스 -15 %\n6 초간 지속.\n최대 5 회 중첩.\n스킬 효과 중첩 시 곱연산 적용된다.\n프리징 릴리즈:\n기본 대미지의 72% 만큼 주술냉기 대미지를 입힌다.\n해당 스킬 지속 시 냉기 저항 관통 +15 %\n최소 4 티어 이상인 경우, 다른 스킬을 5 회 시전할 때마다 해당 스킬이 발동된다.","tags":["자극","주술","냉기","범위","지속"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Permafrost_Cast":{"sourceUrl":"https://tlidb.com/ko/Permafrost_Cast","sourcePageSha256":"95de8b0494a06d71192b79edfa63213bb275074bc728043a2f15898bc581c0e9","locale":"ko","slug":"Permafrost_Cast","season":"SS14","kind":"card","title":"얼음 조소","body":"메인 속성:\n지혜\n시전 속도\n1.25 초\n대미지 배율\n300%\nSimple\n해당 스킬 시전 시 전방의 지면에 펀치를 날리며, 300% 기본 대미지의 주술냉기 대미지를 입힌다.\nDetails\n얼음 조소:\n기본 대미지의 300% 만큼 주술 냉기 대미지를 입힌다.\n해당 스킬이 냉기 적중 대미지를 입힐 시 빙결 을 부여한다.\n최소 3 티어 이상인 경우 적이 보유하고 있는 빙결 3 포인트당 해당 스킬의 대미지 추가 +1 %","tags":["강화 스킬","주술","냉기","범위"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Ice_Earthshaker":{"sourceUrl":"https://tlidb.com/ko/Ice_Earthshaker","sourcePageSha256":"92e7c167725e4d74c563914e38ec93d89bbf68adada135f55211b536c48e21ae","locale":"ko","slug":"Ice_Earthshaker","season":"SS14","kind":"card","title":"땅을 흔드는 얼음폭풍","body":"메인 속성:\n지혜\n시전 속도\n0.67 초\n쿨타임\n8 초\n대미지 배율\n2064%\nSimple\n전방에 얼음 폭풍을 시전하여, 기본 대미지의 2064% 만큼 주술 냉기 대미지를 입힌다.\nDetails\n땅을 흔드는 얼음폭풍:\n기본 대미지의 2064% 만큼 주술 냉기 대미지를 입힌다.\n해당 스킬이 냉기 적중 대미지를 입힐 시 빙결 을 부여한다.","tags":["궁극 스킬","주술","냉기","범위"],"rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}}}};
